-- 44 sample careers (A2, D-137). Every JAMB combination, O'level line and pay range is a starting point only:
-- the owner checks each against this year's JAMB brochure (IBASS) and ticks "checked" in Admin -> Careers.
with u(k, list) as (values
  ('med', array['University of Ibadan','University of Lagos','Obafemi Awolowo University','University of Nigeria, Nsukka','Ahmadu Bello University']),
  ('eng', array['University of Lagos','Obafemi Awolowo University','Federal University of Technology, Akure','Ahmadu Bello University','Covenant University']),
  ('sci', array['University of Ibadan','University of Lagos','University of Nigeria, Nsukka','Obafemi Awolowo University','University of Benin']),
  ('bus', array['University of Lagos','University of Nigeria, Nsukka','Obafemi Awolowo University','Covenant University','University of Ilorin']),
  ('art', array['University of Ibadan','University of Lagos','University of Nigeria, Nsukka','Obafemi Awolowo University','University of Ilorin']),
  ('agr', array['Federal University of Agriculture, Abeokuta','University of Ibadan','Michael Okpara University of Agriculture, Umudike','Ahmadu Bello University','University of Nigeria, Nsukka']),
  ('vet', array['University of Ibadan','Ahmadu Bello University','University of Nigeria, Nsukka','Federal University of Agriculture, Abeokuta','University of Maiduguri']),
  ('opt', array['University of Benin','Abia State University','Imo State University','Madonna University']),
  ('rad', array['University of Nigeria, Nsukka','University of Lagos','Bayero University Kano','Nnamdi Azikiwe University']),
  ('cyb', array['Federal University of Technology, Owerri','Air Force Institute of Technology','Covenant University','University of Lagos']),
  ('pet', array['University of Ibadan','University of Benin','Federal University of Petroleum Resources, Effurun','Covenant University','Federal University of Technology, Owerri']),
  ('aer', array['Air Force Institute of Technology','Federal University of Technology, Minna','Ladoke Akintola University of Technology','Federal University of Technology, Owerri']),
  ('est', array['University of Lagos','Obafemi Awolowo University','Federal University of Technology, Akure','University of Nigeria, Enugu Campus']),
  ('urp', array['University of Lagos','Obafemi Awolowo University','Federal University of Technology, Akure','Ahmadu Bello University']),
  ('ins', array['University of Lagos','University of Jos','Lagos State University','University of Ilorin']),
  ('law', array['University of Lagos','University of Nigeria, Nsukka','Obafemi Awolowo University','University of Ibadan','University of Benin']),
  ('irl', array['Obafemi Awolowo University','University of Lagos','University of Nigeria, Nsukka','Covenant University']),
  ('edu', array['University of Ibadan','University of Nigeria, Nsukka','University of Lagos','Ahmadu Bello University','Tai Solarin University of Education']),
  ('thr', array['University of Ibadan','University of Lagos','University of Benin','University of Jos'])
),
t(k, txt) as (values
  ('SCI5', 'Five credits at one sitting or two: English, Mathematics, Biology, Chemistry and Physics.'),
  ('ENG5', 'Five credits: English, Mathematics, Physics, Chemistry and one other science subject.'),
  ('BUS5', 'Five credits: English, Mathematics, Economics and two other subjects (often Commerce, Accounting or Government).'),
  ('ART5', 'Five credits including English and Literature in English, plus three Arts or Social Science subjects. Mathematics is often asked for at pass level.'),
  ('SOC5', 'Five credits including English and Mathematics, plus three relevant subjects.'),
  ('AGR5', 'Five credits: English, Mathematics, Chemistry, Biology or Agricultural Science, and Physics.'),
  ('TECH5', 'Five credits: English, Mathematics, Physics and two other science subjects.'),
  ('E_DOC', 'Rough guide: about ₦250,000 to ₦600,000 a month as a young doctor in a government hospital; much more as a specialist or abroad.'),
  ('E_HEALTH', 'Rough guide: about ₦150,000 to ₦400,000 a month at the start; more in private and international hospitals.'),
  ('E_ENG', 'Rough guide: about ₦150,000 to ₦500,000 a month at the start; oil and gas and big firms pay much more.'),
  ('E_TECH', 'Rough guide: about ₦200,000 to ₦700,000 a month at the start; skilled people working for foreign companies can earn far more.'),
  ('E_BUS', 'Rough guide: about ₦120,000 to ₦400,000 a month at the start; banks, big firms and professional exams lift it a lot.'),
  ('E_ARTS', 'Rough guide: about ₦100,000 to ₦300,000 a month at the start; it grows with skill, name and the people you work for.'),
  ('E_GOV', 'Rough guide: about ₦100,000 to ₦300,000 a month at the start in the public service; more in NGOs and international bodies.'),
  ('E_AGR', 'Rough guide: about ₦100,000 to ₦350,000 a month at the start; running your own farm or agro business can earn much more.')
),
c(sort, name, field, course, years, summary, skills, uk, ek, jamb, note, ok, after_school) as (values
  (10, 'Medical Doctor', 'Health', 'Medicine and Surgery (MBBS)', 6, 'Doctors find out what is wrong with sick people and treat them. They work in hospitals and clinics, do surgery, and help people stay healthy.', array['Biology and chemistry','Calm under pressure','Caring for people','Long hours of study'], 'med', 'E_DOC', array['bio','chm','phy'], null, 'SCI5', 'One year of housemanship, then NYSC. Then you can train as a specialist (residency).'),
  (20, 'Nurse', 'Health', 'Nursing Science', 5, 'Nurses care for patients every day: they give medicine, watch how patients are doing, and support doctors and families.', array['Caring and patience','Biology','Teamwork','Paying attention to detail'], 'med', 'E_HEALTH', array['bio','chm','phy'], null, 'SCI5', 'Register with the Nursing and Midwifery Council of Nigeria, then NYSC.'),
  (30, 'Pharmacist', 'Health', 'Pharmacy (PharmD)', 6, 'Pharmacists know medicines: they give out the right drugs, explain how to take them, and work in hospitals, shops and drug companies.', array['Chemistry','Accuracy','Talking with people','Memory'], 'med', 'E_HEALTH', array['bio','chm','phy'], 'Some schools accept Mathematics in place of Physics.', 'SCI5', 'One year of internship, then register with the Pharmacy Council of Nigeria.'),
  (40, 'Dentist', 'Health', 'Dentistry and Dental Surgery (BDS)', 6, 'Dentists look after teeth and gums: they fill, fix and remove teeth and teach people how to keep their mouth healthy.', array['Steady hands','Biology','Patience','Care for people'], 'med', 'E_DOC', array['bio','chm','phy'], null, 'SCI5', 'Housemanship, then NYSC and registration as a dentist.'),
  (50, 'Medical Laboratory Scientist', 'Health', 'Medical Laboratory Science', 5, 'They test blood, urine and other samples in the lab so doctors can find out what illness a patient has.', array['Biology and chemistry','Careful work','Using lab machines','Accuracy'], 'med', 'E_HEALTH', array['bio','chm','phy'], null, 'SCI5', 'One year of internship and registration with the medical lab council.'),
  (60, 'Physiotherapist', 'Health', 'Physiotherapy', 5, 'Physiotherapists help people move again after injury, stroke or surgery, using exercise and hands-on treatment.', array['Biology','Encouraging people','Fitness','Patience'], 'med', 'E_HEALTH', array['bio','chm','phy'], null, 'SCI5', 'Internship, then registration with the physiotherapy board.'),
  (70, 'Veterinary Doctor', 'Health', 'Veterinary Medicine (DVM)', 6, 'Vets treat animals: pets, poultry, cattle and fish. They also help keep the food we eat safe.', array['Love for animals','Biology','Calm hands','Problem solving'], 'vet', 'E_HEALTH', array['bio','chm','phy'], null, 'SCI5', 'Register with the Veterinary Council of Nigeria, then NYSC.'),
  (80, 'Optometrist', 'Health', 'Optometry', 6, 'Optometrists test eyes, give glasses and contact lenses, and find eye problems early.', array['Biology and physics','Careful testing','Talking with patients'], 'opt', 'E_HEALTH', array['bio','chm','phy'], null, 'SCI5', 'Internship, then registration with the optometrists board.'),
  (90, 'Radiographer', 'Health', 'Radiography', 5, 'Radiographers take X-rays and scans of the inside of the body so doctors can see what is wrong.', array['Physics','Using machines','Care for patients'], 'rad', 'E_HEALTH', array['bio','chm','phy'], null, 'SCI5', 'Internship, then registration with the radiographers board.'),
  (100, 'Public Health Officer', 'Health', 'Public Health', 4, 'They protect the health of whole communities: clean water, vaccines, disease control and health teaching.', array['Biology','Talking to groups','Planning','Data and reports'], 'med', 'E_HEALTH', array['bio','chm','phy'], 'Some schools accept Mathematics or Geography as the third subject.', 'SCI5', 'NYSC, then work with hospitals, government or NGOs. A master''s degree helps.'),
  (110, 'Software Engineer', 'Engineering and Tech', 'Computer Science or Software Engineering', 4, 'Software engineers build apps, websites and computer systems that people and businesses use every day.', array['Mathematics','Logical thinking','Patience to fix problems','Learning new tools'], 'eng', 'E_TECH', array['mth','phy','chm'], 'Some schools accept Economics, Biology or Geography in place of Chemistry.', 'TECH5', 'NYSC. Build real projects, learn on the job, and keep learning new tools.'),
  (120, 'Data Scientist', 'Engineering and Tech', 'Statistics, Mathematics or Computer Science', 4, 'Data scientists study large amounts of data to find patterns that help companies, banks and government make good choices.', array['Mathematics and statistics','Programming','Curiosity','Explaining results clearly'], 'sci', 'E_TECH', array['mth','phy','chm'], 'Statistics also accepts Economics in place of Chemistry in many schools.', 'TECH5', 'NYSC. Learn Python and SQL and build a portfolio of projects.'),
  (130, 'Cyber Security Expert', 'Engineering and Tech', 'Cyber Security or Computer Science', 4, 'They protect computers, banks and phones from hackers and fraud.', array['Computers and networks','Careful thinking','Honesty','Always learning'], 'cyb', 'E_TECH', array['mth','phy','chm'], null, 'TECH5', 'NYSC. Professional certificates help a lot.'),
  (140, 'Civil Engineer', 'Engineering and Tech', 'Civil Engineering', 5, 'Civil engineers design and build roads, bridges, buildings, dams and drainage.', array['Mathematics and physics','Drawing and design','Teamwork','Safety'], 'eng', 'E_ENG', array['mth','phy','chm'], null, 'ENG5', 'NYSC, then work experience to register with COREN.'),
  (150, 'Mechanical Engineer', 'Engineering and Tech', 'Mechanical Engineering', 5, 'Mechanical engineers design and fix machines: engines, cars, factory machines and generators.', array['Mathematics and physics','Hands-on work','Problem solving'], 'eng', 'E_ENG', array['mth','phy','chm'], null, 'ENG5', 'NYSC, then work experience to register with COREN.'),
  (160, 'Electrical Engineer', 'Engineering and Tech', 'Electrical and Electronics Engineering', 5, 'Electrical engineers work on power, electronics and telecoms: from the national grid to phones and solar systems.', array['Mathematics and physics','Problem solving','Safety'], 'eng', 'E_ENG', array['mth','phy','chm'], null, 'ENG5', 'NYSC, then work experience to register with COREN.'),
  (170, 'Petroleum Engineer', 'Engineering and Tech', 'Petroleum Engineering', 5, 'Petroleum engineers find the best ways to get oil and gas out of the ground safely.', array['Mathematics, physics and chemistry','Working in hard places','Teamwork'], 'pet', 'E_ENG', array['mth','phy','chm'], null, 'ENG5', 'NYSC, then work experience to register with COREN.'),
  (180, 'Chemical Engineer', 'Engineering and Tech', 'Chemical Engineering', 5, 'Chemical engineers turn raw materials into useful products such as fuel, drinks, medicine and plastics in big factories.', array['Chemistry and mathematics','Process thinking','Safety'], 'eng', 'E_ENG', array['mth','phy','chm'], null, 'ENG5', 'NYSC, then work experience to register with COREN.'),
  (190, 'Aeronautical Engineer', 'Engineering and Tech', 'Aerospace or Aeronautical Engineering', 5, 'They design, build and maintain aircraft and their parts.', array['Mathematics and physics','Precision','Teamwork'], 'aer', 'E_ENG', array['mth','phy','chm'], null, 'ENG5', 'NYSC, then licences from the aviation authority for some jobs.'),
  (200, 'Architect', 'Engineering and Tech', 'Architecture', 5, 'Architects design buildings that are safe, useful and beautiful, and guide builders to put them up.', array['Drawing','Mathematics and physics','Creativity','Computer design tools'], 'eng', 'E_ENG', array['mth','phy','geo'], 'Many schools also accept Chemistry, Biology, Economics or Fine Art as the third subject.', null, 'NYSC, then work experience and exams to register with ARCON.'),
  (210, 'Quantity Surveyor', 'Engineering and Tech', 'Quantity Surveying', 5, 'Quantity surveyors work out how much a building or road will cost and keep the money on track while it is built.', array['Mathematics','Careful counting','Negotiation'], 'eng', 'E_ENG', array['mth','phy','eco'], 'Chemistry or Geography can be the third subject in many schools.', null, 'NYSC, then work experience to register with QSRBN.'),
  (220, 'Estate Surveyor', 'Engineering and Tech', 'Estate Management', 5, 'Estate surveyors value, sell, rent and manage land and buildings.', array['Mathematics','Talking with clients','Business sense'], 'est', 'E_BUS', array['mth','eco','geo'], null, null, 'NYSC, then register with ESVARBON.'),
  (230, 'Urban Planner', 'Engineering and Tech', 'Urban and Regional Planning', 5, 'Urban planners decide how towns and cities should grow: where roads, homes, markets and parks go.', array['Geography','Maps and drawing','Planning'], 'urp', 'E_GOV', array['mth','geo','eco'], 'Physics can replace Economics in some schools.', null, 'NYSC, then register with TOPREC.'),
  (240, 'Accountant', 'Business', 'Accounting', 4, 'Accountants keep and check the money records of people, companies and government, and prepare taxes.', array['Mathematics','Honesty','Careful work','Using spreadsheets'], 'bus', 'E_BUS', array['mth','eco','acc'], 'Commerce or Government can replace Financial Accounting in some schools.', 'BUS5', 'NYSC. Then write ICAN or ACCA exams to become a chartered accountant.'),
  (250, 'Banker', 'Business', 'Banking and Finance', 4, 'Bankers help people and businesses save, borrow and invest money.', array['Mathematics','Talking with customers','Trust','Selling'], 'bus', 'E_BUS', array['mth','eco','com'], null, 'BUS5', 'NYSC, then bank trainee programmes. CIBN exams help.'),
  (260, 'Business Manager', 'Business', 'Business Administration', 4, 'Business managers plan and run companies: people, money, sales and day-to-day work.', array['Leadership','Mathematics','Planning','Talking with people'], 'bus', 'E_BUS', array['mth','eco','com'], null, 'BUS5', 'NYSC, then a graduate trainee job. An MBA later helps.'),
  (270, 'Economist', 'Business', 'Economics', 4, 'Economists study how money, jobs and prices work, and advise banks, companies and government.', array['Mathematics','Reading charts and data','Writing reports'], 'bus', 'E_BUS', array['mth','eco','gov'], 'Any one Social Science subject can be the third subject in many schools.', 'BUS5', 'NYSC, then banks, research or government. A master''s degree helps.'),
  (280, 'Marketer', 'Business', 'Marketing', 4, 'Marketers help companies understand customers and sell their products, using adverts, social media and sales teams.', array['Creativity','Talking with people','Social media','Selling'], 'bus', 'E_BUS', array['mth','eco','com'], null, 'BUS5', 'NYSC, then sales or digital marketing roles.'),
  (290, 'Insurance Professional', 'Business', 'Insurance or Actuarial Science', 4, 'They help people and businesses protect themselves from loss, and work out the risk of things going wrong.', array['Mathematics','Trust','Explaining clearly'], 'ins', 'E_BUS', array['mth','eco','acc'], null, 'BUS5', 'NYSC, then professional insurance exams (CIIN).'),
  (300, 'Lawyer', 'Law and Social Sciences', 'Law (LLB)', 5, 'Lawyers advise people and companies about the law, write agreements and speak for clients in court.', array['Reading and writing','Speaking well','Logical arguments','Honesty'], 'law', 'E_BUS', array['lit','gov','crs'], 'Literature in English is a must. The other two can be any Arts or Social Science subjects (for example Government, History, CRS or IRS).', null, 'One year at the Nigerian Law School, call to the Bar, then NYSC.'),
  (310, 'Journalist', 'Law and Social Sciences', 'Mass Communication', 4, 'Journalists find and tell true stories on TV, radio, newspapers and online.', array['Writing','Speaking','Asking good questions','Curiosity'], 'art', 'E_ARTS', array['lit','gov','eco'], 'Literature in English plus any two Arts or Social Science subjects.', 'ART5', 'NYSC, then media houses, PR firms or your own platform.'),
  (320, 'Diplomat', 'Law and Social Sciences', 'International Relations', 4, 'Diplomats represent Nigeria in other countries and help countries work together.', array['Speaking and writing','Current affairs','Languages','Calm negotiation'], 'irl', 'E_GOV', array['gov','his','eco'], 'Government plus any two Arts or Social Science subjects in many schools.', 'SOC5', 'NYSC, then the foreign service exam or international organisations.'),
  (330, 'Political Scientist', 'Law and Social Sciences', 'Political Science', 4, 'They study government, elections and power, and work in public service, politics, media or NGOs.', array['Reading','Writing','Current affairs','Debate'], 'art', 'E_GOV', array['gov','eco','his'], 'Government plus any two Arts or Social Science subjects.', 'SOC5', 'NYSC, then public service, politics, media or NGOs.'),
  (340, 'Psychologist', 'Law and Social Sciences', 'Psychology', 4, 'Psychologists study how people think and behave and help people with stress, learning and mental health.', array['Listening','Biology','Patience','Research'], 'art', 'E_GOV', array['bio','eco','gov'], 'Biology plus any two Science or Social Science subjects in many schools.', 'SOC5', 'NYSC. A master''s degree is needed to work as a clinical psychologist.'),
  (350, 'Social Worker', 'Law and Social Sciences', 'Social Work or Sociology', 4, 'Social workers help families, children and people in hard times get the support they need.', array['Caring','Listening','Patience','Problem solving'], 'art', 'E_GOV', array['gov','eco','geo'], 'Any three Arts or Social Science subjects in many schools.', 'SOC5', 'NYSC, then government welfare offices, hospitals or NGOs.'),
  (360, 'Teacher', 'Arts and Education', 'Education (with a teaching subject)', 4, 'Teachers help students learn and grow. You choose a subject to teach, such as Mathematics, English or Biology.', array['Explaining clearly','Patience','Your teaching subject','Leading a class'], 'edu', 'E_ARTS', array['mth','phy','chm'], 'This is for Education and Mathematics. Each teaching subject has its own combination: check the brochure for yours.', null, 'NYSC, then register with the Teachers Registration Council (TRCN).'),
  (370, 'Writer and Editor', 'Arts and Education', 'English and Literary Studies', 4, 'Writers and editors create and polish books, articles, scripts and content for brands and media.', array['Writing','Reading a lot','Grammar','Creativity'], 'art', 'E_ARTS', array['lit','crs','gov'], 'Literature in English plus any two Arts or Social Science subjects (IRS, History or Government also work).', 'ART5', 'NYSC, then publishing, media, content writing or teaching.'),
  (380, 'Actor and Filmmaker', 'Arts and Education', 'Theatre Arts or Film Studies', 4, 'They act, direct and produce plays, films and TV shows. Nollywood is one of the biggest film industries in the world.', array['Acting or storytelling','Confidence','Teamwork','Creativity'], 'thr', 'E_ARTS', array['lit','gov','crs'], 'Literature in English plus any two Arts subjects in many schools.', 'ART5', 'NYSC, then auditions, short films and building a name.'),
  (390, 'Historian', 'Arts and Education', 'History and International Studies', 4, 'Historians study the past to explain today. They work in teaching, museums, research, media and the foreign service.', array['Reading','Writing','Research','Memory'], 'art', 'E_ARTS', array['his','gov','lit'], 'History plus any two Arts or Social Science subjects in many schools.', 'ART5', 'NYSC, then teaching, research, media or public service.'),
  (400, 'Agricultural Scientist', 'Science and Agriculture', 'Agriculture', 5, 'They help farms grow more food: better seeds, healthy animals, good soil and modern farming.', array['Biology and chemistry','Working outdoors','Business sense'], 'agr', 'E_AGR', array['chm','bio','mth'], 'Agricultural Science can replace Biology, and Physics can replace Mathematics, in many schools.', 'AGR5', 'NYSC, then farms, agro companies, research or your own agribusiness.'),
  (410, 'Microbiologist', 'Science and Agriculture', 'Microbiology', 4, 'Microbiologists study germs such as bacteria and viruses, in hospitals, food and drink companies and research labs.', array['Biology and chemistry','Lab work','Careful notes'], 'sci', 'E_HEALTH', array['bio','chm','phy'], 'Mathematics can replace Physics in many schools.', 'SCI5', 'NYSC, then labs, hospitals, food and drink companies or research.'),
  (420, 'Biochemist', 'Science and Agriculture', 'Biochemistry', 4, 'Biochemists study the chemistry of living things, helping to make medicines, food and new tests for disease.', array['Chemistry and biology','Lab work','Research'], 'sci', 'E_HEALTH', array['bio','chm','phy'], 'Mathematics can replace Physics in many schools.', 'SCI5', 'NYSC, then labs, drug companies, research or further study.'),
  (430, 'Geologist', 'Science and Agriculture', 'Geology', 4, 'Geologists study rocks and the earth to find oil, gas, minerals and water, and to keep buildings safe.', array['Science','Fieldwork','Maps'], 'sci', 'E_ENG', array['chm','mth','phy'], 'Biology or Geography can be the third subject in some schools.', null, 'NYSC, then mining, oil and gas, water or research.'),
  (440, 'Food Scientist', 'Science and Agriculture', 'Food Science and Technology', 5, 'Food scientists make sure the food and drinks we buy are safe, tasty and last long.', array['Chemistry and biology','Lab work','Quality checks'], 'agr', 'E_AGR', array['chm','bio','phy'], 'Mathematics can replace Physics, and Agricultural Science can replace Biology, in many schools.', 'SCI5', 'NYSC, then food and drink companies, NAFDAC or your own food business.')
)
insert into public.careers (name, field, course, years, summary, skills, universities, earnings, jamb_subjects, jamb_note, olevel, after_school, sort)
select c.name, c.field, c.course, c.years, c.summary, c.skills, u.list, e.txt, c.jamb, c.note,
  coalesce(o.txt, case c.name
    when 'Architect' then 'Five credits: English, Mathematics, Physics, plus two of Chemistry, Geography, Fine Art and Technical Drawing.'
    when 'Quantity Surveyor' then 'Five credits: English, Mathematics, Physics, Economics and one other.'
    when 'Estate Surveyor' then 'Five credits: English, Mathematics, Economics and two others.'
    when 'Urban Planner' then 'Five credits: English, Mathematics, Geography and two others.'
    when 'Lawyer' then 'Five credits including English, Literature in English and Mathematics (pass), plus two others.'
    when 'Teacher' then 'Five credits including English and Mathematics and your teaching subject.'
    when 'Geologist' then 'Five credits: English, Mathematics, Chemistry, Physics and one other science.'
  end),
  c.after_school, c.sort
from c join u on u.k = c.uk join t e on e.k = c.ek left join t o on o.k = c.ok;

